// 1. Extracción y sanitización de entrada
const payload = $input.first().json.body || $input.first().json;

const nombre = String(payload.estudiante_nombre || '').trim();
const codigo = String(payload.codigo_uptc || '').trim();
const email = String(payload.email_institucional || '').trim().toLowerCase();
const tipo = String(payload.tipo_tramite || '').trim();
const asunto = String(payload.asignatura_o_lab || '').trim().slice(0, 200);
const desc = String(payload.descripcion || '').trim().slice(0, 2000);
const reqId = payload.request_id || $execution.id;

// 2. Validaciones estrictas UPTC (Matriz P01, P02, P03)
const regexCodigo = /^[0-9]{9}$/;
const regexEmail = /^[^@\s]+@uptc\.edu\.co$/i;
const tiposValidos = ['Tutoria', 'Laboratorio', 'Certificado'];

if (!nombre || nombre.length < 3 || nombre.length > 150) {
  throw new Error('Validación fallida: Nombre de estudiante inválido (3-150 caracteres).');
}
if (!regexCodigo.test(codigo)) {
  throw new Error('Validación fallida: El código UPTC debe contener exactamente 9 dígitos.');
}
if (!regexEmail.test(email) || email.length > 255) {
  throw new Error('Validación fallida: El correo debe ser institucional y terminar en @uptc.edu.co.');
}
if (!tiposValidos.includes(tipo)) {
  throw new Error(`Validación fallida: Trámite '${tipo}' no soportado.`);
}
if (!desc || desc.length < 5) {
  throw new Error('Validación fallida: Descripción insuficiente.');
}

return {
  json: {
    valido: true,
    estudiante_id: payload.estudiante_id || null,
    estudiante_nombre: nombre,
    codigo_uptc: codigo,
    email_institucional: email,
    tipo_tramite: tipo,
    asignatura_o_lab: asunto,
    descripcion: desc,
    request_id: reqId,
    estado: 'Pendiente',
    creado_en: new Date().toISOString()
  }
};
